prompt --application/shared_components/user_interface/templates/list/liquid_tabs
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(917169364533517839)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TLiquidTabs #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<div class="amc-TLiquidTabs-scroller">',
'<div class="amc-TLiquidTabs-rail">',
'<span class="amc-TLiquidTabs-goo" aria-hidden="true"><span class="amc-TLiquidTabs-blob amc-TLiquidTabs-blob--tail"></span><span class="amc-TLiquidTabs-blob"></span></span>',
'<ul class="amc-TLiquidTabs-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>',
'</div>',
'</div>'))
,p_list_template_current=>'<li class="amc-TLiquidTabs-item is-current"><a class="amc-TLiquidTabs-link is-lit" href="#LINK#" aria-current="page"><span class="amc-TLiquidTabs-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TLiquidTabs-label">#TEXT#</span><span class="amc-TLiquidTabs-badge">#A01#</span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TLiquidTabs-item"><a class="amc-TLiquidTabs-link" href="#LINK#"><span class="amc-TLiquidTabs-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TLiquidTabs-label">#TEXT#</span><span class="amc-TLiquidTabs-badge">#A01#</span></a></li>'
,p_list_template_name=>'AMC Liquid Tabs'
,p_internal_name=>'AMC_TPL_LIQUID_TABS'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-liquid-tabs.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-liquid-tabs.css'
,p_a01_label=>'Count badge'
,p_list_template_comment=>'List template for tab navigation. Each entry is a real link; the current entry gets aria-current=page. Attribute 1 is a count badge that is hidden when empty. With JavaScript the indicator is a liquid pill that stretches toward the hovered or keyboard-focused tab and returns to the current tab; without JavaScript, and under prefers-reduced-motion, the current tab shows a static pill and nothing moves. The strip scrolls horizontally in narrow containers, fades its edges while scrolling and scrolls the current tab into view. Template options: Solid pill fills the indicator with the primary color; Liquid underline turns it into a stretching drop under the label; Fill width spreads the tabs across the region; Large raises the tab height; No track removes the tray behind the tabs. Forced-colors mode shows the current tab with a system outline.'
);
end;
